	/**
	 * Default Constructor
	 */
    public ReportService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ReportEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ReportRepository.class) );
		this.validator		= applicationContext.getBean(ReportValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Report
	 */
		public Report createReport( CreateReportCommand command ) {

		Report entity = new Report();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setReportId( command.getReportId() );
            entity.setReportName( command.getReportName() );
            entity.setGeneratedAt( command.getGeneratedAt() );
            entity.setFileUrl( command.getFileUrl() );
            entity.setReportType( command.getReportType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Report {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateReportCommand
	 * @return		Report
	 */
	public Report updateReport( UpdateReportCommand command ) {

		Report entity = new Report();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setReportId( command.getReportId() );
            entity.setReportName( command.getReportName() );
            entity.setGeneratedAt( command.getGeneratedAt() );
            entity.setFileUrl( command.getFileUrl() );
            entity.setAdAccount( command.getAdAccount() );
            entity.setCampaign( command.getCampaign() );
            entity.setLineItem( command.getLineItem() );
            entity.setReportType( command.getReportType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Report {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteReportCommand
	 */
	public void delete( DeleteReportCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getReportId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Report {0} ", id );

	}

	/**
	 * Method to retrieve the Report via ReportFetchOneSummary
	 * @param 	summary ReportFetchOneSummary
	 * @return 	ReportFetchOneResponse
	 */
	public Report getReport( ReportFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ReportFetchOneSummary arg cannot be null" );

		Report entity = null;
		UUID id = summary.getReportId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Report using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Reports
	 *
	 * @return 	List<Report>
	 */
    public List<Report> getAllReport() {
		List<Report> list = projector.findAll( new FindAllReportQuery() );
		return list;
	}

	/**
	 * assign AdAccount on Report
	 * @param		command AssignAdAccountToReportCommand
	 */
	public void assignAdAccount( AssignAdAccountToReportCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignAdAccount(command.getReportId(), command.getAssignment());

	}

	/**
	 * unAssign AdAccount on Report
	 * @param		command UnAssignAdAccountFromReportCommand
	 */
	public void unAssignAdAccount( UnAssignAdAccountFromReportCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignAdAccount(command.getReportId());
	}
	
